import{prepareRotors,advanceRotors,RenderBudget}from'./animation.js?v=balance-8';
import{initMaterials}from'./voxels.js?v=balance-8';
import{buildEquipment}from'./equipment.js?v=balance-8';
const B=globalThis.BABYLON;
export class PartPreview{
 constructor(canvas){this.canvas=canvas;this.engine=new B.Engine(canvas,true,{stencil:true,preserveDrawingBuffer:false});this.budget=new RenderBudget(globalThis.devicePixelRatio||1);this.budget.apply(this.engine);this.scene=new B.Scene(this.engine);this.scene.clearColor=new B.Color4(.035,.055,.075,1);initMaterials(this.scene);const light=new B.HemisphericLight('inspection sky',B.Vector3.Up(),this.scene);light.intensity=1.2;const key=new B.DirectionalLight('inspection rim',new B.Vector3(.4,-.6,.5),this.scene);key.intensity=1.8;this.camera=new B.ArcRotateCamera('part turntable',-Math.PI*.65,Math.PI*.37,12,B.Vector3.Zero(),this.scene);this.camera.attachControl(canvas,true);this.camera.wheelPrecision=35;this.camera.lowerBetaLimit=.12;this.camera.upperBetaLimit=Math.PI-.12;this.camera.minZ=.02;this.scene.activeCamera=this.camera;this.dragging=false;canvas.addEventListener('pointerdown',()=>this.dragging=true);for(const event of['pointerup','pointercancel','pointerleave'])canvas.addEventListener(event,()=>this.dragging=false);this.glow=new B.GlowLayer('inspection radiance',this.scene,{mainTextureFixedSize:256,blurKernelSize:32});this.glow.intensity=.65;this.key='';this.resize=new ResizeObserver(()=>this.engine.resize());this.resize.observe(canvas);}
 show(type,choice){const key=type+'/'+choice.slot+'/'+choice.level+'/'+(choice.module?.id||'stock');if(key===this.key)return;this.key=key;this.kit?.root.dispose(false,false);this.kit=buildEquipment(this.scene,type,choice);prepareRotors(this.kit);const meshes=this.kit.parts.map(p=>p.mesh);let min=new B.Vector3(Infinity,Infinity,Infinity),max=min.scale(-1);for(const mesh of meshes){mesh.computeWorldMatrix(true);const b=mesh.getBoundingInfo().boundingBox;min=B.Vector3.Minimize(min,b.minimumWorld);max=B.Vector3.Maximize(max,b.maximumWorld);}const center=min.add(max).scale(.5),radius=Math.max(1,B.Vector3.Distance(min,max)*.5);this.camera.setTarget(center);this.camera.radius=radius*2.8;this.camera.lowerRadiusLimit=radius*1.15;this.camera.upperRadiusLimit=radius*5;this.camera.alpha=-Math.PI*.65;this.engine.resize();return this.kit;}
 render(dt){if(!this.kit||!this.canvas.closest('dialog')?.open)return;if(!this.dragging)this.camera.alpha+=dt*.18;const s=this.kit.surfaces,t=performance.now()/1000;for(const a of s.ailerons)a.node.rotation.x=Math.sin(t)*a.side*.3;for(const e of s.elevators)e.rotation.x=Math.sin(t)*.3;for(const r of s.rudders)r.rotation.y=Math.sin(t)*.3;for(const f of s.flaps)f.rotation.x=-.35*(Math.sin(t)*.5+.5);advanceRotors(this.kit,dt,{throttle:0,speed:0},true);this.scene.render();if(this.budget.sample(dt))this.budget.apply(this.engine);}
}
